/**
 * Data layer for the Aggregate Stats views — STATIC build.
 *
 * Loads two baked JSON files once (public/data, regenerated by server scripts/bake-static.ts)
 * and serves everything client-side, so the deployed site needs no backend or database.
 *
 * Backend honesty: only top-division LEAGUE titles exist (no cup/other trophies), so `cup`/`oth`
 * are 0 and a manager's cabinet holds only championships. Data is a frozen snapshot — re-bake +
 * re-deploy to refresh.
 */

import { leagueFlagUrl } from './flags.js';

export interface Country {
  code: string;
  name: string;
}

export interface Manager {
  userId: number;
  login: string;
  c: string;
  team: string;
  lg: number;
  main: number; // main national cup wins (attributed)
  sec: number; // secondary/consolation cup wins (attributed)
  hm: number; // Hattrick Masters wins (the global champions-of-champions cup)
  sn: number; // Seasonal Cups wins (global recurring tournaments, e.g. Supporter Week Trophy)
  oth: number;
  lgLast: number; // reigning league titles (current champion of that league)
  mainLast: number; // reigning main-cup titles (current holder of that cup)
  secLast: number; // reigning secondary/consolation-cup titles
  hmLast: number; // reigning Hattrick Masters title (holder of the most recent edition)
  snLast: number; // reigning Seasonal Cups titles (holder of the most recent edition)
}

export interface TrophyItem {
  main: string;
  sub: string;
  season: string;
  last?: boolean; // the reigning/most-recent trophy of its competition
  flag?: string | null; // country-flag URL (by leagueId); null for the country-less Masters
}

export interface TrophyCabinet {
  champ: TrophyItem[];
  main: TrophyItem[];
  sec: TrophyItem[];
  other: TrophyItem[]; // the Hattrick Masters
  seasonal: TrophyItem[]; // Seasonal Cups (Supporter Week Trophy)
}

export interface Winner {
  season: number;
  club: string;
  manager: string;
}

export interface CupWinner {
  season: number;
  club: string;
  manager: string;
}

export interface CupRoll {
  cupId: number;
  cupName: string;
  isMain: boolean;
  cupLevel: number;
  cupLevelIndex: number;
  winners: CupWinner[];
}

export interface CupCountry {
  leagueId: number;
  country: string;
  cups: CupRoll[];
}

interface RawCup {
  country: string;
  leagueId?: number;
  season: number;
  club: string;
  cup: string;
  last?: boolean;
}
interface RawManager {
  userId: number;
  userName: string;
  nationality: string;
  lg: number;
  main: number;
  sec: number;
  hm?: number;
  sn?: number;
  lgLast?: number;
  mainLast?: number;
  secLast?: number;
  hmLast?: number;
  snLast?: number;
  titles: Array<{ country: string; leagueId?: number; season: number; club: string; last?: boolean }>;
  cupsMain: RawCup[];
  cupsSec: RawCup[];
  masters?: RawCup[];
  seasonal?: RawCup[];
}
interface RawLeague {
  leagueId: number;
  country: string;
  champions: Array<{ season: number; club: string; manager: string }>;
}

let bundle: Promise<{ managers: RawManager[]; leagues: RawLeague[] }> | null = null;
function load() {
  if (!bundle) {
    bundle = Promise.all([
      fetch('/data/managers.json').then((r) => r.json() as Promise<RawManager[]>),
      fetch('/data/leagues.json').then((r) => r.json() as Promise<RawLeague[]>),
    ]).then(([managers, leagues]) => ({ managers, leagues }));
  }
  return bundle;
}

// Cups load lazily on their own — the Cup winners view is the only consumer, and cups.json is
// large, so we don't pull it into the initial bundle. Missing file (older bake) → empty list.
let cupsBundle: Promise<CupCountry[]> | null = null;
function loadCups() {
  if (!cupsBundle) {
    cupsBundle = fetch('/data/cups.json')
      .then((r) => (r.ok ? (r.json() as Promise<CupCountry[]>) : []))
      .catch(() => []);
  }
  return cupsBundle;
}

export async function getCupCountries(): Promise<Country[]> {
  const cups = await loadCups();
  return cups.map((c) => ({ code: String(c.leagueId), name: c.country }));
}

export async function getCups(leagueId: string): Promise<CupRoll[]> {
  const cups = await loadCups();
  return cups.find((c) => String(c.leagueId) === leagueId)?.cups ?? [];
}

export async function getNationalities(): Promise<Country[]> {
  const { managers } = await load();
  const counts = new Map<string, number>();
  for (const m of managers) counts.set(m.nationality, (counts.get(m.nationality) ?? 0) + 1);
  return [...counts.entries()]
    .filter(([n]) => n && n !== 'Unknown')
    .sort((a, b) => b[1] - a[1])
    .map(([nationality, n]) => ({ code: nationality, name: `${nationality} (${n})` }));
}

export async function getLeagues(): Promise<Country[]> {
  const { leagues } = await load();
  return leagues.map((l) => ({ code: String(l.leagueId), name: l.country }));
}

/**
 * Fallback for bakes that predate the per-item `last` flag: each country's latest league season.
 * Each country runs its own season clock, so the reigning season is per-country. Lets league
 * reigning resolve client-side before a re-bake; baked `last` flags take precedence when present.
 */
function latestLeagueSeasonByCountry(leagues: RawLeague[]): Map<string, number> {
  const latest = new Map<string, number>();
  for (const l of leagues)
    for (const c of l.champions) {
      const cur = latest.get(l.country);
      if (cur === undefined || c.season > cur) latest.set(l.country, c.season);
    }
  return latest;
}

export async function getManagers(nationality?: string): Promise<Manager[]> {
  const { managers, leagues } = await load();
  const latestByCountry = latestLeagueSeasonByCountry(leagues);

  return managers
    .filter((m) => !nationality || nationality === 'ALL' || m.nationality === nationality)
    .map((m) => {
      const titles = m.titles ?? [];
      const lgLast =
        m.lgLast ??
        (titles.some((t) => t.last !== undefined)
          ? titles.filter((t) => t.last).length
          : titles.filter((t) => latestByCountry.get(t.country) === t.season).length);
      return {
        userId: m.userId,
        login: m.userName,
        c: m.nationality,
        team: '',
        lg: m.lg,
        main: m.main ?? 0,
        sec: m.sec ?? 0,
        hm: m.hm ?? 0,
        sn: m.sn ?? 0,
        oth: 0,
        lgLast,
        mainLast: m.mainLast ?? (m.cupsMain ?? []).filter((c) => c.last).length,
        secLast: m.secLast ?? (m.cupsSec ?? []).filter((c) => c.last).length,
        hmLast: m.hmLast ?? (m.masters ?? []).filter((c) => c.last).length,
        snLast: m.snLast ?? (m.seasonal ?? []).filter((c) => c.last).length,
      };
    });
}

export async function getCabinet(userId: number): Promise<TrophyCabinet> {
  const { managers, leagues } = await load();
  const m = managers.find((x) => x.userId === userId);
  // Mirror getManagers' league fallback so an expanded cabinet stays consistent with the chart
  // under "Reigning only" even before a re-bake (cups need the bake — no `last`, no fallback).
  const latestByCountry = latestLeagueSeasonByCountry(leagues);
  const champ = (m?.titles ?? []).map((t) => ({
    main: `${t.country} champions`,
    sub: t.club,
    season: 'S' + t.season,
    last: t.last ?? latestByCountry.get(t.country) === t.season,
    flag: leagueFlagUrl(t.leagueId),
  }));
  const cupItems = (cups?: RawCup[]) => (cups ?? []).map((t) => ({ main: t.cup, sub: t.club, season: 'S' + t.season, last: t.last, flag: leagueFlagUrl(t.leagueId) }));
  // `other` carries the Hattrick Masters and `seasonal` the Seasonal Cups — each its own category
  // (see bake.ts / sync/masters.ts / sync/seasonal.ts). Both are country-less, so no flag.
  return { champ, main: cupItems(m?.cupsMain), sec: cupItems(m?.cupsSec), other: cupItems(m?.masters), seasonal: cupItems(m?.seasonal) };
}

export async function getWinners(leagueId: string): Promise<Winner[]> {
  const { leagues } = await load();
  const l = leagues.find((x) => String(x.leagueId) === leagueId);
  return l ? l.champions : [];
}
